const maxResults = 50;
const listTypes = [
  { listType: 'Bestseller', label: '베스트셀러' },
  { listType: 'BlogBest', label: '북플 베스트셀러' },
  { listType: 'ItemNewAll', label: '신간 전체' },
  { listType: 'ItemNewSpecial', label: '주목할 만한 신간' },
  { listType: 'ItemEditorChoice', label: '편집자 추천' },
];

// 알라딘 국내도서 > 소설/시/희곡 하위 카테고리 CID.
// 요청한 제외 범위: 한국소설, 영미소설, 일본소설, 로맨스소설, 추리/미스터리소설, 판타지/환상문학, 세계의 소설, 시, 과학소설(SF), 역사소설 제외.
const categoryGroups = [
  { categoryId: 50921, label: '프랑스소설', pages: 5 },
  { categoryId: 50922, label: '독일소설', pages: 4 },
  { categoryId: 50923, label: '중국소설', pages: 4 },
  { categoryId: 52650, label: '러시아소설', pages: 4 },
  { categoryId: 50920, label: '스페인/중남미소설', pages: 4 },
  { categoryId: 50933, label: '액션/스릴러소설', pages: 4 },
  { categoryId: 50955, label: '세계의 문학', pages: 4 },
  { categoryId: 50931, label: '호러.공포소설', pages: 3 },
  { categoryId: 50948, label: '희곡', pages: 3 },
  { categoryId: 50932, label: '무협소설', pages: 2 },
];

const batches = [];
for (const group of categoryGroups) {
  for (const list of listTypes) {
    for (let page = 1; page <= group.pages; page += 1) {
      batches.push({
        json: {
          category: group.label,
          categoryId: group.categoryId,
          listType: list.listType,
          listLabel: list.label,
          start: page,
          maxResults,
        },
      });
    }
  }
}
return batches;

const rawResponse = $input.first().json;
const batch = $('검색 배치 순회').first().json;
const normalize = value => String(value || '')
  .normalize('NFKC')
  .toLowerCase()
  .replace(/[“”‘’"']/g, '')
  .replace(/\([^)]*\)/g, ' ')
  .replace(/[^0-9a-zA-Z가-힣\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const cleanText = value => String(value || '')
  .normalize('NFKC')
  .replace(/[\u0000-\u001F\u007F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const parsePayload = value => {
  if (value && typeof value === 'object' && Array.isArray(value.item)) return value;
  const raw = typeof value === 'string'
    ? value
    : typeof value?.data === 'string'
      ? value.data
      : typeof value?.body === 'string'
        ? value.body
        : '';
  if (!raw) return value || {};
  const cleaned = raw.trim().replace(/^\w+\s*=\s*/, '').replace(/;\s*$/, '');
  return JSON.parse(cleaned);
};
const hasBrokenOrOriginalScript = value => /[\uFFFD\u3040-\u30FF\u3400-\u9FFF]/.test(String(value || ''));
const hasHangul = value => /[가-힣]/.test(String(value || ''));
const isKoreanTitleOnly = value => /^[가-힣\s]+$/.test(String(value || '').trim());
const parseDate = value => /^\d{4}-\d{2}-\d{2}$/.test(String(value || '')) ? value : null;
const truncateText = (value, maxLength) => Array.from(String(value || '')).slice(0, maxLength).join('');
const isFictionCategory = categoryName => cleanText(categoryName).replace(/\s/g, '').includes('소설/시/희곡');
const collectionPattern = /(모음집|작품집|단편집|단편선|중단편선|소설집|선집|전집|문집|문학전집|대표작|대표작품|걸작선|명작선|베스트|컬렉션|앤솔로지|옴니버스|합본|세트|시리즈|완역본\s*세트|\b[0-9]+권\b|\b[0-9]+\s*권\b|\b[상중하]\b)/;
const isNonNovelTitle = title => /(속의|연구|이해|문학사|비평|평론|해설|강의|읽기|작법|이론|사전|논문|총서|선집|전집|교재|기독교|불교|철학|역사와|문화와)/.test(title) || collectionPattern.test(title);
const isNonNovelCategory = categoryName => /(문학이론|문학비평|작가론|문학사|종교|인문학|대학교재|논문|비평|전집|선집|작품집|단편집)/.test(categoryName);

const response = parsePayload(rawResponse);
const items = Array.isArray(response?.item) ? response.item : [];
const books = items
  .map((item, index) => ({
    title: cleanText(item.title),
    author: truncateText(cleanText(item.author), 20),
    category: batch.category,
    isbn13: cleanText(item.isbn13 || item.isbn),
    publisher: cleanText(item.publisher),
    published_at: parseDate(item.pubDate),
    aladin_item_id: item.itemId ? Number(item.itemId) : null,
    aladin_link: cleanText(item.link),
    aladin_cover_url: cleanText(item.cover),
    aladin_category_name: cleanText(item.categoryName),
    aladin_rank: item.bestRank ? Number(item.bestRank) : ((Number(batch.start) - 1) * Number(batch.maxResults)) + index + 1,
  }))
  .filter(book => book.title && book.author)
  .filter(book => isFictionCategory(book.aladin_category_name))
  .filter(book => !isNonNovelTitle(book.title) && !isNonNovelCategory(book.aladin_category_name))
  .filter(book => isKoreanTitleOnly(book.title))
  .filter(book => !hasBrokenOrOriginalScript(book.title) && !hasBrokenOrOriginalScript(book.author))
  .map(book => ({
    json: {
      ...book,
      skip_insert: false,
      normalized_title: normalize(book.title),
      normalized_author: normalize(book.author),
    },
  }));

if (books.length === 0) {
  return [{
    json: {
      skip_insert: true,
      listType: batch.listType,
      start: batch.start,
      category: batch.category,
      aladin_item_count: items.length,
      reason: '문학 베스트셀러 응답은 있었지만 필터 통과 도서가 없습니다.',
    },
  }];
}

return books;
